def stop_boundary():
    return dict(kind='before_next_VM_call_after_diagnostic_formatter',stop_before=hex(VM_CALL),VM_call_executed=False,wrapper_executed=False,target_executed=False)

def project_next_call(row):
    row=deepcopy(row);raw=bytes.fromhex(row.pop('wrapper_code_hex'))[:NEXT_WRAPPER_SIZE]
    row['wrapper_code_hex']=raw.hex();row['wrapper_code_sha256']=raw_hash(raw)
    assert 'descriptor_hex' not in row
    return row

def read_static(path,libc):
    rows={}
    for domain,p in (('main',path),('libc',libc)):
        with p.open('rb') as f:
            elf=ELFFile(f)
            for off,size in CODE_RANGES[domain]:
                raw=previous.previous.previous.previous.elf_bytes(elf,f,off,size)
                rows[domain+':'+hex(off)]=dict(size=size,hex=raw.hex(),sha256=raw_hash(raw))
    return rows

def independent_controls(path,libc):
    table=controls.exports(libc)
    cases=[controls.compare(path,libc,base,label,table) for base in controls.BASES for label in controls.PROFILES]
    guards=controls.guards(path,libc)
    assert cases==CONTROL_SPECS and guards==ROLLBACK_SPECS
    return cases,guards

def run(path,libc):
    parent=prior_evidence();p=previous.previous.previous.previous.bootstrap.module_prefix();p.digest.verify_images(path,libc)
    code=read_static(path,libc);assert {k:v['sha256'] for k,v in code.items()}==CODE_SHA256
    def create(control):
        s=PostDiagnosticFormatScenario(control);s.path=path;s.continue_to_svc=True;return s
    rows=p.digest.context.replay(path,libc,case_controls=[p.CONTROL],_extension_factory=create,
        _request_profile=p.digest.previous.previous.name.previous.previous.PROFILE['name'],_handler_read_profile=p.digest.context.NULL_PAYLOAD_READ_PROFILE['name'])
    assert len(rows)==1
    cases,guards=independent_controls(path,libc)
    return dict(schema=SCHEMA,claims=claims_for(),providers=providers(),source_fingerprints=source_fingerprints(),input_provenance=provenance(parent),
        static_code=code,native_controls=cases,component_rollback_checks=guards,case_result=rows[0],case_result_sha256=digest(rows[0]))

def overlaps(address,size,region):
    a=int(address,16);b=int(region['address'],16);return a<b+region['size'] and b<a+size

def validate(data):
    parent=prior_evidence();old=parent['case_result']
    assert set(data)=={'schema','claims','providers','source_fingerprints','input_provenance','static_code','native_controls','component_rollback_checks','case_result','case_result_sha256'}
    assert data['schema']==SCHEMA and data['claims']==claims_for() and data['providers']==providers()
    assert data['source_fingerprints']==source_fingerprints() and data['input_provenance']==provenance(parent)
    assert data['native_controls']==CONTROL_SPECS and len(CONTROL_SPECS)==20
    assert data['component_rollback_checks']==ROLLBACK_SPECS and len(ROLLBACK_SPECS)==12
    assert set(data['static_code'])==set(CODE_SHA256)
    for domain,ranges in CODE_RANGES.items():
        assert len(ranges)==len({off for off,size in ranges})
        for off,size in ranges:
            entry=data['static_code'][domain+':'+hex(off)];raw=bytes.fromhex(entry['hex'])
            assert set(entry)=={'hex','size','sha256'} and len(raw)==entry['size']==size and raw_hash(raw)==entry['sha256']==CODE_SHA256[domain+':'+hex(off)]
    row=data['case_result'];assert data['case_result_sha256']==digest(row) and row['control']==old['control']
    assert set(row)=={'control','retained_scope_leave','instruction_observations','instruction_trace_sha256','observed_code_sha256','snapshots',
        'native_writes','services','format_arguments','next_VM_call','observation_sites','observed_code','new_allocator_events','protected_ranges',
        'protected_write_events','protection_activation','stop_boundary'}|set(EXPECTED['ledgers'])
    assert row['retained_scope_leave']==dict(case_result_sha256=digest(old),verified_fields=list(PARENT_FIELDS))
    sites=row['observation_sites'];code=row['observed_code'];h=hashlib.sha256()
    assert len(sites)==row['instruction_observations']==EXPECTED['instruction_observations']<MAX_OBSERVATIONS and set(sites)==set(code)
    assert sites[:7]==['main:'+hex(x) for x in (VM_CALL,WRAPPER,WRAPPER+4,WRAPPER+8,WRAPPER+12,WRAPPER+16,TARGET)]
    assert sites[-1]=='main:'+hex(VM_CALL) and sites.count('main:'+hex(VM_CALL))==2
    assert sites.count('main:'+hex(VM_RESUME))==sites.count('main:'+hex(TARGET))==1 and 'libc:'+hex(VSNPRINTF) in sites
    for key in sites:
        raw=bytes.fromhex(code[key]);assert len(raw)==4;h.update(key.encode()+raw)
    assert h.hexdigest()==row['instruction_trace_sha256']==EXPECTED['instruction_trace_sha256']
    assert digest(code)==row['observed_code_sha256']==EXPECTED['observed_code_sha256']
    for domain,ranges in CODE_RANGES.items():
        for off,size in ranges:
            raw=data['static_code'][domain+':'+hex(off)]['hex']
            for pc in range(off,off+size,4):
                if domain+':'+hex(pc) in code:assert code[domain+':'+hex(pc)]==raw[(pc-off)*2:(pc-off+4)*2]
    for key in ('snapshots','native_writes','services','format_arguments','next_VM_call','new_allocator_events','protected_ranges'):
        assert row[key]==EXPECTED[key],key
    snapshots=row['snapshots'];first=snapshots[0];last=snapshots[-1];returned=next(x for x in snapshots if x['kind']=='formatter_callback_return');prior=old['snapshots'][-1]
    assert [x['kind'] for x in snapshots]==['formatter_VM_call','wrapper_entry','formatter_entry','formatter_callback_return','before_next_VM_call']
    assert first['index']==1 and last['index']==len(sites) and all(a['index']<b['index'] for a,b in zip(snapshots,snapshots[1:]))
    for x in snapshots:
        assert sites[x['index']-1]==x['pc']
        assert x['live_state']==first['live_state']
        assert not any(k in x['live_state'] for k in previous.RETIRED_SCOPE_FIELDS)
        assert x['VM_state_address']==prior['VM_state_address']
        assert x['string_object']['address']==first['string_object']['address']==prior['live_state']['heap_string_object_address']
        assert x['string_object']['vtable_offset']=='0x34f5f8' and x['string_object']['payload_terminated'] is True
        assert set(x['registers'])==(set() if x['kind']=='before_next_VM_call' else {'x0','x30'})
        if x['index']<=returned['index']:assert x['descriptor_sha256']==first['descriptor_sha256']
    assert first['descriptor_address']==old['next_VM_call']['descriptor_address'] and first['descriptor_sha256']==old['next_VM_call']['descriptor_sha256']
    assert first['VM_cursor']==returned['VM_cursor']==prior['VM_cursor']=='0x10a2c8'
    assert first['SP']==returned['SP']==prior['SP'] and first['callee_saved_sha256']==returned['callee_saved_sha256']==prior['callee_saved_sha256']
    assert first['string_object']['length_u32']==0 and first['string_object']['capacity_u32']==8
    assert returned['string_object']==last['string_object']
    assert snapshots[2]['registers']['x0']==first['string_object']['address']
    args=row['format_arguments'];assert args['format_address']==old['next_VM_call']['format_address']
    assert args['W2_width']==4 and args['W2_sha256']==old['next_VM_call']['argument_W2_sha256']
    assert args['ambient_GP_and_FP_arguments_not_consumed_verified'] is False
    assert args['format_is_single_signed_decimal'] or args['format_is_single_unsigned_decimal']
    assert args['format_width']==3 and len(args['format_including_NUL_sha256'])==64
    assert row['protected_write_events']==[]
    expected_fixed=[r for r in old['protected_ranges'] if r['label'] not in ('new_heap_string_object','new_heap_string_payload')]
    obj=returned['string_object']
    assert row['protected_ranges']==expected_fixed+[
        dict(label='formatted_string_object',address=obj['address'],size=24),dict(label='formatted_string_payload',address=obj['payload_address'],size=obj['capacity_u32'])]
    assert row['protection_activation']==dict(retained_regions_from_index=1,formatted_object_after_index=returned['index'])
    for w in row['native_writes']:
        assert set(w)=={'index','PC','address','size'} and sites[w['index']-1]==w['PC'] and w['size']>0
        regions=row['protected_ranges'] if w['index']>returned['index'] else row['protected_ranges'][:-2]
        assert not any(overlaps(w['address'],w['size'],r) for r in regions)
        assert not overlaps(w['address'],w['size'],dict(address=first['string_object']['address'],size=8))
        if w['index']<=returned['index']:assert not overlaps(w['address'],w['size'],dict(address=first['descriptor_address'],size=48))
    formats=[s for s in row['services'] if s['kind']=='vsnprintf_PLT'];assert len(formats)==1
    assert formats[0]['format_address']==args['format_address'] and formats[0]['width']>obj['length_u32']
    for service in row['services']:assert sites[service['index']-1]==service['PC']
    for key,value in EXPECTED['ledgers'].items():assert row[key]==value,key
    for key in ('inherited_JNI_calls','inherited_libc_SVC','inherited_main_SVC','inherited_syscall_172','inherited_syscall_173','late_jni','java_dispatch'):
        assert row[key]==old[key],key
    call=row['next_VM_call'];assert call['index']==len(sites) and call['VM_cursor_offset']==last['VM_cursor']
    assert call['callsite_offset']==hex(VM_CALL) and call['descriptor_width']==48
    assert call['wrapper_offset']==hex(NEXT_WRAPPER) and call['target_offset']==hex(NEXT_TARGET)
    assert call['wrapper_code_hex']==data['static_code']['main:'+hex(NEXT_WRAPPER)]['hex']
    assert len(bytes.fromhex(call['wrapper_code_hex']))==NEXT_WRAPPER_SIZE and raw_hash(bytes.fromhex(call['wrapper_code_hex']))==call['wrapper_code_sha256']
    assert call['VM_call_executed'] is call['wrapper_executed'] is call['target_executed'] is False
    assert row['stop_boundary']==stop_boundary()

def damaged_evidence_rejected(data):
    changes=[(('claims','next_VM_call_executed'),True),(('claims','complete_standalone_signer_verified'),True),
        (('claims','whole_physical_stack_and_GP_FP_varargs_ABI_compared'),True),
        (('claims','formatted_payload_matches_supplied_W2_decimal_conversion'),False),(('providers','new_providers'),['hidden']),
        (('source_fingerprints','owners','formatter_model'),'0'*64),(('case_result','retained_scope_leave','case_result_sha256'),'0'*64),
        (('case_result','instruction_observations'),0),(('case_result','instruction_trace_sha256'),'0'*64),(('case_result','observed_code_sha256'),'0'*64),
        (('case_result','snapshots',-1,'live_state','counter_u32'),1),(('case_result','snapshots',-1,'live_state','protected_regions_sha256'),'0'*64),
        (('case_result','snapshots',-1,'live_state','cache_mutex_state_u16'),1),(('case_result','snapshots',-2,'SP'),'0x0'),
        (('case_result','snapshots',-2,'callee_saved_sha256'),'0'*64),(('case_result','snapshots',-1,'live_state','diagnostic','mutex_state_u16'),0x4001),
        (('case_result','snapshots',-1,'live_state','diagnostic','owner_u32'),137),(('case_result','snapshots',-1,'live_state','initialized_word_is_one'),False),
        (('case_result','snapshots',-1,'live_state','scope_fields'),{}),(('case_result','snapshots',-1,'string_object','payload_including_NUL_sha256'),'0'*64),
        (('case_result','snapshots',-1,'string_object','capacity_u32'),0),(('case_result','snapshots',-1,'string_object','length_u32'),0),
        (('case_result','snapshots',-1,'string_object','payload_terminated'),False),(('case_result','snapshots',-1,'string_object','vtable_offset'),'0x0'),
        (('case_result','snapshots',-1,'registers'),{'x2':'0x1'}),(('case_result','format_arguments','W2_sha256'),'0'*64),
        (('case_result','format_arguments','W2_value'),1),(('case_result','format_arguments','raw_format'),'omitted'),
        (('case_result','services',0,'index'),0),(('case_result','native_writes',0,'size'),99),
        (('case_result','protection_activation','formatted_object_after_index'),0),(('case_result','next_VM_call','target_offset'),'0x0'),
        (('case_result','next_VM_call','descriptor_sha256'),'0'*64),(('case_result','next_VM_call','wrapper_code_sha256'),'0'*64),
        (('case_result','next_VM_call','target_executed'),True),(('case_result','next_VM_call','descriptor_hex'),'omitted'),
        (('case_result','new_allocator_events'),[['hidden']]),(('case_result','protected_write_events'),['hidden']),
        (('case_result','stop_boundary','VM_call_executed'),True),(('case_result','raw_identifier'),'omitted'),(('case_result','raw_allocation'),'omitted'),
        (('raw_identifier',),'omitted'),(('native_controls',0,'native_snapshot_input'),True),
        (('component_rollback_checks',0,'all_pages_unchanged'),False)]
    for key in EXPECTED['ledgers']:changes.append((('case_result',key),{}))
    for key in CODE_SHA256:changes.append((('static_code',key,'sha256'),'0'*64))
    for path,value in changes:
        bad=deepcopy(data);obj=bad
        for key in path[:-1]:obj=obj[key]
        obj[path[-1]]=value
        if path[0]=='case_result':bad['case_result_sha256']=digest(bad['case_result'])
        try:validate(bad)
        except (AssertionError,KeyError,ValueError,TypeError):continue
        raise AssertionError(f'damaged formatter evidence accepted: {path}')
    return len(changes)

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--elf',type=Path);parser.add_argument('--libc',type=Path)
    mode=parser.add_mutually_exclusive_group();mode.add_argument('--capture',action='store_true');mode.add_argument('--replay',action='store_true')
    args=parser.parse_args()
    if (args.capture or args.replay) and (not args.elf or not args.libc):parser.error('--capture and --replay require --elf and --libc')
    if args.capture:
        if EVIDENCE.exists():raise FileExistsError('frozen evidence already exists; refusing overwrite')
        data=run(args.elf,args.libc);validate(data);rejected=damaged_evidence_rejected(data)
        with EVIDENCE.open('x',encoding='utf-8',newline='\n') as out:out.write(json.dumps(data,indent=2)+'\n')
    else:
        data=json.loads(EVIDENCE.read_text(encoding='utf-8'));validate(data);rejected=damaged_evidence_rejected(data)
        if args.replay:assert run(args.elf,args.libc)==data,'fresh diagnostic formatter replay differs'
    print(json.dumps(dict(schema=SCHEMA,native_controls=len(data['native_controls']),component_rollback_checks=len(data['component_rollback_checks']),
        damaged_evidence_rejected=rejected,instruction_observations=data['case_result']['instruction_observations'],original_formatter_returned=True,
        next_VM_call_executed=False,complete_standalone_signer_verified=False)))
if __name__=='__main__':main()
